//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			Fôring - Felles                                                                                                                                                                                                                                                                            
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0			2024-04-08			William Veim			Initial release   
//	1.0.1			2024-04-27			William Veim			Buxfix AVG weight calculation   
//	1.0.2			2024-05-08			William Veim			Lagt til egendefinerte fôrplaner 
//
//===============================================================================================================================

(*************************************************************************
 *	VARIABLE CONTROL
 *************************************************************************)

Current_Time := 								TruncTod(DT_TO_TOD(In:=GetTime()), _SEC); // Retrives current time
Current_TimeSeconds :=	 				LINT_TO_DINT(TodToSec(Current_Time)); // Converts time to sec
ConvertHours := 								Current_TimeSeconds / 3600; // 3600 sekunder per time
ConvertMinutes := 							((Current_TimeSeconds MOD 3600) / 60) * 100 / 60; // Konverter minutter til området 0-100
Wrk_TableSize:=								SizeOfAry(EXT_Feeding)-1;
RE_MidnightPulse(Clk:=					Current_Time=TIME_OF_DAY#00:00:00.00);
DtToDateStruct(In:=							GetTime(), DateStruct=>DateStruct);

(*************************************************************************
 *	INITIALISING VARIABELS
 *************************************************************************)

IF NOT EXT_FeedingCommon.INT_Data.Initialise THEN
	
	//Temp solution (delete when loaded to all applications)
	IF EXT_FeedingCommon.EXT_Operator.Feed_Table1.Custom_Name = '' AND EXT_FeedingCommon.EXT_Operator.Feed_Table2.Custom_Name = '' AND EXT_FeedingCommon.EXT_Operator.Feed_Table3.Custom_Name = '' THEN
	EXT_FeedingCommon.EXT_Operator.Feed_Table1.Custom_Name:= 'Feed table 1';
	EXT_FeedingCommon.EXT_Operator.Feed_Table2.Custom_Name:= 'Feed table 2';
	EXT_FeedingCommon.EXT_Operator.Feed_Table3.Custom_Name:= 'Feed table 3';
	END_IF;
	 
	//Temp solution (delete when loaded to all applications) 
	IF EXT_FeedingCommon.EXT_Operator.FeedType1_Name = '' AND EXT_FeedingCommon.EXT_Operator.FeedType2_Name = '' THEN
	EXT_FeedingCommon.EXT_Operator.FeedType1_Name := '1mm feed';
	EXT_FeedingCommon.EXT_Operator.FeedType2_Name := '2mm feed';
	EXT_FeedingCommon.EXT_Operator.FeedType3_Name := '3mm feed';
	EXT_FeedingCommon.EXT_Operator.FeedType4_Name := '4mm feed';
	EXT_FeedingCommon.EXT_Operator.FeedType5_Name := '5mm feed';
	EXT_FeedingCommon.EXT_Operator.FeedType6_Name := '6mm feed';
	EXT_FeedingCommon.EXT_Operator.FeedType7_Name := '7mm feed';
	EXT_FeedingCommon.EXT_Operator.FeedType8_Name := '8mm feed';
	EXT_FeedingCommon.EXT_Operator.FeedType9_Name := '9mm feed';
	EXT_FeedingCommon.EXT_Operator.FeedType10_Name := '10mm feed';
	END_IF;

	EXT_FeedingCommon.INT_Data.Initialise:=TRUE;

END_IF;

//Assigning index for each structure
IF P_First_Run THEN
	
	FOR Wrk_IndexA:=0 TO Wrk_TableSize DO 
		EXT_Feeding[Wrk_IndexA].INT_Data.CurrentIndex:=Wrk_IndexA;
	END_FOR;
	
END_IF;

//Index control (for FB to retrive feed factor and SGR value)
//Increment index
Inc(EXT_FeedingCommon.INT_Data.RetriveIndex);

//Out of array bounds
IF EXT_FeedingCommon.INT_Data.RetriveIndex > Wrk_TableSize THEN
	EXT_FeedingCommon.INT_Data.RetriveIndex:=0;
END_IF;

(*************************************************************************
 *	CALCULATING FEED PLAN DATA
 *************************************************************************)

//Calculate active feed columm
Wrk_Hour:= STRING_TO_UINT(LEFT(DELETE(TodToString(Current_Time), 13,6),2));
Wrk_Minute:=STRING_TO_UINT(RIGHT(DELETE(TodToString(Current_Time), 13,6),2));
EXT_FeedingCommon.EXT_Operator.FeedCol_ActiveIndex:=(Wrk_Hour * 2) + (Wrk_Minute / 30);
FeedPlan_SumValues:=0;
IF Wrk_Minute < 30 THEN
	FeedPlan_CurrentCol_Progress:= UINT_TO_REAL(Wrk_Minute) / REAL#30;
ELSE
	FeedPlan_CurrentCol_Progress:= UINT_TO_REAL(Wrk_Minute-30) / REAL#30;
END_IF;

CASE EXT_FeedingCommon.INT_Data.RetriveIndex OF
	
	0: //Calculate feed plan 1
	
		FOR Wrk_Index:= 0 TO 47 DO
			FeedPlan_SumValues:= FeedPlan_SumValues + EXT_FeedingCommon.EXT_Operator.Feed_Plan1.Columm_Value[Wrk_Index];
		END_FOR;
		
		IF EXT_FeedingCommon.EXT_Operator.Feed_Plan1.Columm_Value[EXT_FeedingCommon.EXT_Operator.FeedCol_ActiveIndex] > 0 THEN
			EXT_FeedingCommon.INT_Data.FeedPlan1_Intensity	:= ScaleTrans(SclIn:=FeedPlan_CurrentCol_Progress, 
																														X0:=0, 
																														Y0:=EXT_FeedingCommon.EXT_Operator.Feed_Plan1.Columm_Value[EXT_FeedingCommon.EXT_Operator.FeedCol_ActiveIndex], 
																														X1:=1, 
																														Y1:=EXT_FeedingCommon.EXT_Operator.Feed_Plan1.Columm_Value[EXT_FeedingCommon.EXT_Operator.FeedCol_ActiveIndex+1]) / ULINT_TO_REAL(FeedPlan_SumValues) / 30;
		ELSE
			EXT_FeedingCommon.INT_Data.FeedPlan1_Intensity:= 0;
		END_IF;
		
	1: //Calculate feed plan 2
	
		FOR Wrk_Index:= 0 TO 47 DO
			FeedPlan_SumValues:= FeedPlan_SumValues + EXT_FeedingCommon.EXT_Operator.Feed_Plan2.Columm_Value[Wrk_Index];
		END_FOR;

		IF EXT_FeedingCommon.EXT_Operator.Feed_Plan2.Columm_Value[EXT_FeedingCommon.EXT_Operator.FeedCol_ActiveIndex] > 0 THEN
			EXT_FeedingCommon.INT_Data.FeedPlan2_Intensity	:= ScaleTrans(SclIn:=FeedPlan_CurrentCol_Progress, 
																														X0:=0, 
																														Y0:=EXT_FeedingCommon.EXT_Operator.Feed_Plan2.Columm_Value[EXT_FeedingCommon.EXT_Operator.FeedCol_ActiveIndex], 
																														X1:=1, 
																														Y1:=EXT_FeedingCommon.EXT_Operator.Feed_Plan2.Columm_Value[EXT_FeedingCommon.EXT_Operator.FeedCol_ActiveIndex+1]) / ULINT_TO_REAL(FeedPlan_SumValues) / 30;
		ELSE
			EXT_FeedingCommon.INT_Data.FeedPlan2_Intensity:= 0;
		END_IF;
		
	2: //Calculate feed plan 3
	
		FOR Wrk_Index:= 0 TO 47 DO
			FeedPlan_SumValues:= FeedPlan_SumValues + EXT_FeedingCommon.EXT_Operator.Feed_Plan3.Columm_Value[Wrk_Index];
		END_FOR;

		IF EXT_FeedingCommon.EXT_Operator.Feed_Plan3.Columm_Value[EXT_FeedingCommon.EXT_Operator.FeedCol_ActiveIndex] > 0 THEN
			EXT_FeedingCommon.INT_Data.FeedPlan3_Intensity	:= ScaleTrans(SclIn:=FeedPlan_CurrentCol_Progress, 
																														X0:=0, 
																														Y0:=EXT_FeedingCommon.EXT_Operator.Feed_Plan3.Columm_Value[EXT_FeedingCommon.EXT_Operator.FeedCol_ActiveIndex], 
																														X1:=1, 
																														Y1:=EXT_FeedingCommon.EXT_Operator.Feed_Plan3.Columm_Value[EXT_FeedingCommon.EXT_Operator.FeedCol_ActiveIndex+1]) / ULINT_TO_REAL(FeedPlan_SumValues) / 30;
		ELSE
			EXT_FeedingCommon.INT_Data.FeedPlan3_Intensity:= 0;
		END_IF;
		
END_CASE;

(*************************************************************************
 *	STATISTIC DATA
 *************************************************************************)

//Accumulating feed amount
Clear(EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedWeek);
Clear(EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedMonth);
Clear(EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedYear);

EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedWeek:=		Wrk_FeedAmountWeek +	EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedToday;
EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedMonth:=	Wrk_FeedAmountMonth +	EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedToday;
EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedYear:=		Wrk_FeedAmountYear +		EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedToday;

IF RE_MidnightPulse.Q THEN
	Wrk_FeedAmountWeek:= 	Wrk_FeedAmountWeek + 	EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedToday;
	Wrk_FeedAmountMonth:= 	Wrk_FeedAmountMonth + EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedToday;
	Wrk_FeedAmountYear:= 		Wrk_FeedAmountYear + 	EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedToday;
END_IF;

//Checks if new week
IF Sample_Week <> GetWeekOfYear(In:=GetTime()) THEN
	Clear(Wrk_FeedAmountWeek);
	Clear(EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedWeek);
END_IF;

//Checks if new month
IF Sample_Month <> DateStruct.Month THEN
	Clear(Wrk_FeedAmountMonth);
	Clear(EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedMonth);
END_IF;
			
//Checks if new year
IF GetWeekOfYear(In:=GetTime()) = 1 AND Sample_Week <> GetWeekOfYear(In:=GetTime()) THEN
	Clear(Wrk_FeedAmountYear);
	Clear(EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedYear);
END_IF;

// Sampling
Sample_Week := 	GetWeekOfYear(In:=GetTime());
Sample_Month := DateStruct.Month;

(*************************************************************************
 *	ACCUMULATING DATA FROM FEEDING
 *************************************************************************)

IF Wrk_TableSize > 1 THEN
	
	//Reset values
	Clear(EXT_FeedingCommon.EXT_Operator.Biomass_Total_Current);
	Clear(EXT_FeedingCommon.EXT_Operator.Biomass_Total_Tomorrow);
	Clear(EXT_FeedingCommon.EXT_Operator.DeadFish_Total);
	Clear(EXT_FeedingCommon.EXT_Operator.Fish_Total);
	Clear(EXT_FeedingCommon.EXT_Operator.Weight_AVG_Total);
	Clear(EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedToday);
	Clear(EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedYesterday);
	Clear(EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_PlannedToday);
	Clear(EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_PlannedTomorrow);
	
	//Summing values in array
	FOR Wrk_IndexA:=0 TO Wrk_TableSize DO
		
		EXT_FeedingCommon.EXT_Operator.Biomass_Total_Current := 						HE_REAL_CheckValid(EXT_FeedingCommon.EXT_Operator.Biomass_Total_Current + EXT_Feeding[Wrk_IndexA].EXT_Operator.Biomass_Current);
		EXT_FeedingCommon.EXT_Operator.Biomass_Total_Tomorrow := 					HE_REAL_CheckValid(EXT_FeedingCommon.EXT_Operator.Biomass_Total_Tomorrow+ EXT_Feeding[Wrk_IndexA].EXT_Operator.Biomass_Tomorrow);
		EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedToday:=					HE_REAL_CheckValid(EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedToday + EXT_Feeding[Wrk_IndexA].EXT_Operator.Feed_Amount_Current_Total);
		EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedYesterday:=			HE_REAL_CheckValid(EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_FedYesterday + EXT_Feeding[Wrk_IndexA].EXT_Statistics.Feed_Amount_Yesterday);
		EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_PlannedToday:= 			HE_REAL_CheckValid(EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_PlannedToday+ EXT_Feeding[Wrk_IndexA].EXT_Operator.Feed_Amount_Today);
		EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_PlannedTomorrow:= 	HE_REAL_CheckValid(EXT_FeedingCommon.EXT_Operator.FeedAmountTotal_PlannedTomorrow+ EXT_Feeding[Wrk_IndexA].EXT_Operator.Feed_Amount_Tomorrow);
		EXT_FeedingCommon.EXT_Operator.DeadFish_Total := 									HE_REAL_CheckValid(EXT_FeedingCommon.EXT_Operator.DeadFish_Total + EXT_Feeding[Wrk_IndexA].EXT_Statistics.Group_Amount_Deadfish);
		EXT_FeedingCommon.EXT_Operator.Fish_Total := 												HE_REAL_CheckValid(EXT_FeedingCommon.EXT_Operator.Fish_Total + EXT_Feeding[Wrk_IndexA].EXT_Operator.Amount_Fish);
		
	END_FOR;
	
	//Calculate average weight
	EXT_FeedingCommon.EXT_Operator.Weight_AVG_Total := HE_REAL_CheckValid((EXT_FeedingCommon.EXT_Operator.Biomass_Total_Current * 1000000.0) / EXT_FeedingCommon.EXT_Operator.Fish_Total);
	
END_IF;
